if(random(100) > 90)
{
   var randomNumber = random(3);
   if(randomNumber == 0)
   {
      _parent.gotoAndPlay(10);
   }
   else if(randomNumber == 1)
   {
      _parent.gotoAndPlay(20);
   }
   else
   {
      _parent.gotoAndPlay(30);
   }
}

